-- Postcondition: 0 transmission faults with NULL severity, 24 rows total.
DO $$
DECLARE null_n integer;
DECLARE total_n integer;
BEGIN
  SELECT count(*) INTO null_n FROM catalog_component_faults WHERE component_type = 'transmission' AND severity IS NULL;
  IF null_n <> 0 THEN
    RAISE EXCEPTION 'Expected 0 transmission faults with NULL severity, found %.', null_n;
  END IF;

  SELECT count(*) INTO total_n FROM catalog_component_faults WHERE component_type = 'transmission';
  IF total_n <> 24 THEN
    RAISE EXCEPTION 'Expected 24 transmission faults total, found %.', total_n;
  END IF;
END $$;

